<?php
require __DIR__.'/auth.php';require __DIR__.'/database.php';
if(!empty($_SESSION['user'])){header('Location: index.php');exit;}
$error='';$submitted=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        verify_csrf();$d=$_POST;$trade=trim($d['trade_name']??'');$field=$d['business_field']??'';$email=strtolower(trim($d['email']??''));$username=trim($d['username']??'');$name=trim($d['name']??'');$contact=trim($d['contact_number']??'');$password=$d['password']??'';$subscription=$d['subscription_mode']??'';
        if($trade===''||$name===''||$contact===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Complete the required company and contact details.');
        if(!in_array($field,['mobile_shop','car_rental','grocery','office'],true))throw new RuntimeException('Choose a valid business field.');
        if(!in_array($subscription,['monthly','yearly'],true))throw new RuntimeException('Choose a subscription mode.');
        if(!preg_match('/^[A-Za-z0-9_.@-]{3,80}$/',$username))throw new RuntimeException('Username must be 3–80 characters and use letters, numbers, dot, underscore, @ or hyphen.');
        if(strlen($password)<8)throw new RuntimeException('Password must be at least 8 characters.');
        $pdo=db();$pdo->beginTransaction();
        $q=$pdo->prepare('SELECT 1 FROM users WHERE username=?');$q->execute([$username]);if($q->fetchColumn())throw new RuntimeException('That username is already in use.');
        $q=$pdo->prepare('SELECT 1 FROM companies WHERE email=?');$q->execute([$email]);if($q->fetchColumn())throw new RuntimeException('A request already exists for this email.');
        do{$code='COMP-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('SELECT 1 FROM companies WHERE company_code=?');$q->execute([$code]);}while($q->fetchColumn());
        $q=$pdo->prepare('INSERT INTO companies(company_code,trade_name,business_field,email,contact_number,subscription_mode,status) VALUES(?,?,?,?,?,? ,"pending")');$q->execute([$code,$trade,$field,$email,$contact,$subscription]);$company=(int)$pdo->lastInsertId();
        $q=$pdo->prepare('INSERT INTO company_sections(company_id,section_key,enabled) SELECT ?,section_key,0 FROM business_sections');$q->execute([$company]);
        $section=['mobile_shop'=>'mobile_shop','car_rental'=>'car_rental','grocery'=>'grocery','office'=>'office'][$field];$q=$pdo->prepare('UPDATE company_sections SET enabled=1 WHERE company_id=? AND section_key=?');$q->execute([$company,$section]);
        $q=$pdo->prepare('INSERT INTO users(company_id,name,username,password_hash,role,active) VALUES(?,?,?,?,"admin",0)');$q->execute([$company,$name,$username,password_hash($password,PASSWORD_DEFAULT)]);
        $pdo->commit();$submitted=$code;
    }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Could not submit. Check whether the email or username is already registered.':$e->getMessage();}
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Company registration · Fora</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-page"><main class="login-shell registration-shell"><section class="login-art"><div class="brand"><span class="brand-mark">F</span><span>FORA<span class="brand-light"> BUSINESS WORKSPACE</span></span></div><div class="login-copy"><span class="eyebrow">A WORKSPACE FOR YOUR BUSINESS</span><h1>Register<br><em>your company.</em></h1><p>Submit your details. A Super Admin will review the request and enable the appropriate workspaces.</p></div><div class="login-art-foot">DUBAI · UAE <span>BUSINESS PORTAL</span></div></section><section class="login-form-wrap"><div class="login-form registration-form"><span class="eyebrow">COMPANY REQUEST</span><h2><?= $submitted?'Request received':'Create your company request' ?></h2><?php if($submitted):?><p>Your request is waiting for Super Admin approval. Save this company code for reference:</p><div class="registration-code"><?=htmlspecialchars($submitted)?></div><p class="muted">Your account will be available after approval.</p><a class="button button-dark button-full" href="login.php">Return to sign in</a><?php else:?><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><label>Company / trade name<input name="trade_name" required maxlength="180"></label><label>Business field<select name="business_field" required><option value="">Choose a field</option><option value="mobile_shop">Mobile Shop</option><option value="car_rental">Rent a Car</option><option value="grocery">Grocery</option><option value="office">Office</option></select></label><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Username<input name="username" required autocomplete="username"></label><label>Contact person name<input name="name" required autocomplete="name"></label><label>Password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>Contact number<input type="tel" name="contact_number" required></label><label>Subscription mode<select name="subscription_mode" required><option value="">Choose a plan</option><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select></label><button class="button button-dark button-full">Submit for approval <span>→</span></button><div class="login-note">Already registered? <a href="login.php">Sign in</a></div></form><?php endif;?></div></section></main></body></html>
